def handle_network_request(url, params, headers):
    try:
        import requests
        response = requests.get(url, params=params, headers=headers)
        if response.status_code == 200:
            return response.json()
        elif response.status_code == 404:
            return {"error": "Not Found"}
        else:
            return {"error": "Unexpected status code: " + str(response.status_code)}
    except requests.exceptionsProxyError as e:
        return {"error": "Proxy error: " + str(e)}
    except requests.exceptionsRequestException as e:
        return {"error": "Request error: " + str(e)}

